DROP TABLE IF EXISTS `form_poe_item_requirements`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `form_poe_item_requirements` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `subpap_id` bigint unsigned NOT NULL,
  `account_id` bigint unsigned NOT NULL,
  `suggested_itemreq_id` bigint unsigned DEFAULT NULL,
  `itemreq_txt` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `per_capita_cost` double NOT NULL,
  `unit_id` bigint unsigned DEFAULT NULL,
  `unit` text COLLATE utf8mb4_unicode_ci,
  `procurement_mode_id` bigint unsigned NOT NULL,
  `qty_pax` int NOT NULL,
  `no_of_days` int NOT NULL,
  `total` double DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `form_poe_item_requirements_subpap_id_foreign` (`subpap_id`),
  KEY `form_poe_item_requirements_account_id_foreign` (`account_id`),
  KEY `form_poe_item_requirements_unit_id_foreign` (`unit_id`),
  KEY `form_poe_item_requirements_procurement_mode_id_foreign` (`procurement_mode_id`),
  KEY `form_poe_item_requirements_suggested_itemreq_id_foreign` (`suggested_itemreq_id`),
  CONSTRAINT `form_poe_item_requirements_account_id_foreign` FOREIGN KEY (`account_id`) REFERENCES `chart_of_accounts` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `form_poe_item_requirements_procurement_mode_id_foreign` FOREIGN KEY (`procurement_mode_id`) REFERENCES `procurement_modes` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `form_poe_item_requirements_subpap_id_foreign` FOREIGN KEY (`subpap_id`) REFERENCES `form_poe_sub_paps` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `form_poe_item_requirements_suggested_itemreq_id_foreign` FOREIGN KEY (`suggested_itemreq_id`) REFERENCES `list_of_item_requirements` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `form_poe_item_requirements_unit_id_foreign` FOREIGN KEY (`unit_id`) REFERENCES `units` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1905 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
